from math import gcd


def make_keys(p, q, e):
    n = p * q
    phi = (p - 1) * (q - 1)
    if gcd(e, phi) != 1:
        raise ValueError(f"e={e} is not coprime to phi={phi}")
    d = pow(e, -1, phi)
    return (n, e), (n, d)


def rsa_sign(m, private_key):
    n, d = private_key
    return pow(m, d, n)


